int snd_usb_midi_create(struct snd_card *card, struct usb_interface *iface,
                        struct list_head *midi_list,
                        const struct snd_usb_audio_quirk *quirk)
{
    struct snd_usb_midi *midi;
    int err;

    midi = kzalloc(sizeof(*midi), GFP_KERNEL);
    if (!midi)
        return -ENOMEM;

    midi->card = card;
    midi->iface = iface;
    midi->usb_id = le16_to_cpu(quirk->vendor_id);
    midi->quirk = *quirk;

    if ((quirk->vendor_id != 0xffff) || (quirk->product_id != 0xffff)) {
        midi->midi_out_ep = quirk->data[0];
        midi->midi_in_ep = quirk->data[1];
    }

    err = snd_usb_midi_instantiate(midi);
    if (err < 0)
        goto error;

    err = snd_rawmidi_new(card, "USB MIDI", -1, 1, 1, &midi->midi);
    if (err < 0)
        goto error;

    strcpy(midi->midi->name, "USB MIDI Device");
    midi->midi->private_data = midi;

    list_add(&midi->list, midi_list);

    return 0;

error:
    kfree(midi);
    return err;
}

int snd_usb_midi_create(struct snd_card *card, struct usb_interface *iface,
                        struct list_head *midi_list,
                        const struct snd_usb_audio_quirk *quirk)
{
    struct snd_usb_midi *midi;
    int err;

    midi = kzalloc(sizeof(*midi), GFP_KERNEL);
    if (!midi)
        return -ENOMEM;

    midi->card = card;
    midi->iface = iface;
    midi->chip = &card->chip;

    err = snd_usb_midi_detect_endpoints(midi, quirk);
    if (err < 0)
        goto error;

    err = snd_usb_midi_outport_create(midi);
    if (err < 0)
        goto error;

    err = snd_usb_midi_inport_create(midi);
    if (err < 0)
        goto error;

    err = snd_rawmidi_new(card, "USB MIDI", -1, midi->out_ports, midi->in_ports, &midi->rmidi);
    if (err < 0)
        goto error;

    midi->rmidi->private_data = midi;
    strcpy(midi->rmidi->name, "USB MIDI");

    if (quirk && quirk->setup)
        quirk->setup(midi);

    list_add(&midi->list, midi_list);

    return 0;

error:
    kfree(midi);
    return err;
}

int snd_usb_midi_create(struct snd_card *card, struct usb_interface *iface,
                        struct list_head *midi_list,
                        const struct snd_usb_audio_quirk *quirk)
{
        struct snd_usb_midi *midi;
        int err;

        midi = kzalloc(sizeof(*midi), GFP_KERNEL);
        if (!midi)
                return -ENOMEM;

        midi->chip.card = card;
        midi->iface = iface;
        midi->quirk = quirk;

        err = snd_usb_midi_detect_endpoints(midi);
        if (err < 0)
                goto error;

        err = snd_usbmidi_create(midi, &midi->ports);
        if (err < 0)
                goto error;

        INIT_LIST_HEAD(&midi->list);
        list_add(&midi->list, midi_list);

        return 0;

error:
        kfree(midi);
        return err;
}

int snd_usb_midi_create(struct snd_card *card, struct usb_interface *iface,
                        struct list_head *midi_list,
                        const struct snd_usb_audio_quirk *quirk)
{
    struct snd_usb_midi *midi;
    int err;

    midi = kzalloc(sizeof(*midi), GFP_KERNEL);
    if (!midi)
        return -ENOMEM;

    midi->card = card;
    midi->iface = iface;

    err = snd_usb_midi_detect_endpoints(midi, quirk);
    if (err < 0)
        goto error;

    err = snd_rawmidi_new(card, "USB MIDI", -1, 1, 1, &midi->ports[0].rmidi);
    if (err < 0)
        goto error;

    midi->ports[0].rmidi->private_data = &midi->ports[0];
    midi->ports[1].rmidi->private_data = &midi->ports[1];

    list_add(&midi->list, midi_list);

    return 0;

error:
    kfree(midi);
    return err;
}
